    letter-spacing: var(--tracking-tight);
  }
  .typography details:not(.not-typography details) p:first-of-type {
    margin-top: calc(var(--spacing) * 2);
  }
  .typography mark:not(.not-typography mark) {
    background-color: var(--color-yellow-300);
  }
  .typography small:not(.not-typography small) {
    font-size: var(--text-xs);
    line-height: 1;
  }

  @media (min-width: 1024px) {
    .typography h1:not(.not-typography h1) {
      font-size: var(--text-5xl);
      line-height: var(--text-5xl--line-height);
    }
  }
}

@layer utils {
  .text-gradient {
    @apply bg-clip-text text-transparent;
  }

  .bg-grid {
    --bg-grid-color: hsl(0 0% 100% / 0.1);
    background-color: transparent; /* Couleur de fond */
    background-image:
      linear-gradient(90deg, var(--bg-grid-color) 1px, transparent 1px),
      linear-gradient(180deg, var(--bg-grid-color) 1px, transparent 1px);
    background-size: 64px 64px; /* Taille de la grille */
  }
}

/* Other styles */

.citation {
  position: relative;
  display: inline-block;
  padding: 4px;
  border-radius: 0.5rem;
  color: var(--foreground);
  font-style: italic;
  --gap: -16px;
}

.citation::before {
  content: "“";
  font-size: 3rem;
  position: absolute;
  top: -12px;
  left: -12px;
  line-height: 1;
  color: hsl(var(--primary));
}

.citation::after {
  content: "”";
  font-size: 3rem;
  position: absolute;
  bottom: -16px;
  right: -4px;
  line-height: 1;
  color: hsl(var(--primary));
}

.citation strong {
  font-weight: 700;
  background: hsl(var(--primary) / 0.5);
  display: inline;
  padding: 2px;
  margin: -2px;
}

.dot-pattern {
  background-color: var(--dot-background);
  opacity: 0.8;
  background-image: radial-gradient(
    var(--dot-color) 0.5px,
    var(--dot-background) 0.5px
  );
  background-size: var(--size, 10px) var(--size, 10px);
}

html.dark .shiki,
html.dark .shiki span {
  color: var(--shiki-dark) !important;
  background-color: var(--shiki-dark-bg) !important;
  /* Optional, if you also want font styles */
  font-style: var(--shiki-dark-font-style) !important;
  font-weight: var(--shiki-dark-font-weight) !important;
  text-decoration: var(--shiki-dark-text-decoration) !important;
}

.prose {
  code:not(pre code) {
    &::after {
      display: none;
    }
    &::before {
      display: none;
    }

    background-color: var(--muted);
    padding: calc(var(--spacing) * 1.5);
    border-radius: var(--radius);
  }
}
.chat-prose {
  h1,
  h2,
  h3 {
    font-size: 1rem !important;
  }
}

.code-example {
  & pre {
    margin: 0 !important;
  }
}

