    96→        return getFullOrg(
    97→          updatedUser.session.activeOrganizationId,
    98→          updatedUser.session.userId,
    99→        );
   100→      }
   101→    } catch (err) {
   102→      logger.error("Error setting active organization", err);
   103→    }
   104→  }
   105→
   106→  const firstOrg = await prisma.organization.findFirst({
