    10→/**
    11→ * Helper function to create a test account
    12→ * @returns Object containing the test user's credentials
    13→ */
    14→export async function createTestAccount(options: {
    15→  page: Page;
    16→  callbackURL?: string;
    17→  initialUserData?: { name: string; email: string; password: string };
    18→  admin?: boolean;
    19→}) {
    20→  // Generate fake user data
    21→  const userData = options.initialUserData ?? {
    22→    name: faker.person.fullName(),
    23→    email: getUserEmail(),
    24→    password: faker.internet.password({ length: 12, memorable: true }),
    25→  };
    26→
    27→  // Navigate to signup page
    28→  await options.page.goto(`/auth/signup?callbackUrl=${options.callbackURL}`);
    29→
    30→  // Fill out the form
    31→  await options.page.getByLabel("Name").fill(userData.name);
    32→  await options.page.getByLabel("Email").fill(userData.email);
    33→  await options.page.locator('input[name="password"]').fill(userData.password);
    34→  await options.page
    35→    .locator('input[name="verifyPassword"]')
    36→    .fill(userData.password);
    37→
    38→  // Submit the form
    39→  await options.page.getByRole("button", { name: /sign up/i }).click();
    40→
    41→  // Wait for navigation to complete - we should be redirected to the callback URL
    42→  if (options.callbackURL) {
    43→    await options.page.waitForLoadState("networkidle");
    44→    // Extract pathname from callbackURL and match it regardless of domain
    45→    const callbackPath = new URL(options.callbackURL, "http://localhost")
    46→      .pathname;
    47→    await options.page.waitForURL(
    48→      new RegExp(
    49→        `^[^/]*//[^/]*${callbackPath.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}`,
    50→      ),
    51→      {
    52→        timeout: 30000,
    53→      },
    54→    );
    55→  }
    56→
    57→  if (options.admin) {
    58→    const user = await retry(
    59→      async () =>
    60→        prisma.user.findUniqueOrThrow({
    61→          where: { email: userData.email },
    62→        }),
